CREATE OR REPLACE FUNCTION public.save_fixture_result(p_fixture_id uuid, p_home_score integer, p_away_score integer, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_fixture     public.manager_fixtures%ROWTYPE;
  v_event_type  TEXT;
  v_was_completed BOOLEAN;
BEGIN
  IF p_home_score < 0 OR p_away_score < 0 THEN
    RAISE EXCEPTION 'save_fixture_result: scores must be non-negative';
  END IF;

  SELECT * INTO v_fixture
  FROM public.manager_fixtures
  WHERE id = p_fixture_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'save_fixture_result: fixture % not found', p_fixture_id;
  END IF;

  v_was_completed := v_fixture.status = 'COMPLETED';
  v_event_type    := CASE WHEN v_was_completed THEN 'RESULT_EDITED' ELSE 'RESULT_CREATED' END;

  UPDATE public.manager_fixtures
  SET home_score   = p_home_score,
      away_score   = p_away_score,
      status       = 'COMPLETED',
      completed_at = COALESCE(v_fixture.completed_at, NOW()),
      updated_at   = NOW()
  WHERE id = p_fixture_id;

  INSERT INTO public.manager_tournament_events
    (tournament_id, event_type, actor_user_id, metadata)
  VALUES (
    v_fixture.tournament_id,
    v_event_type,
    p_actor_user_id,
    jsonb_build_object(
      'fixture_id',           p_fixture_id,
      'home_team_id',         v_fixture.home_team_id,
      'away_team_id',         v_fixture.away_team_id,
      'home_score',           p_home_score,
      'away_score',           p_away_score,
      'previous_home_score',  v_fixture.home_score,
      'previous_away_score',  v_fixture.away_score
    )
  );

  RETURN jsonb_build_object(
    'fixture_id',  p_fixture_id,
    'home_score',  p_home_score,
    'away_score',  p_away_score,
    'was_edit',    v_was_completed
  );
END;
$function$
